import React, { useState } from 'react';
import { Network, Activity, Filter, Search } from 'lucide-react';
import { formatTimestamp, toHex } from '../utils/helpers';

const NetworkMonitor = ({ networkTraffic, isRunning }) => {
  const [filter, setFilter] = useState('all');
  const [searchTerm, setSearchTerm] = useState('');

  const getFilteredTraffic = () => {
    let filtered = [...networkTraffic].reverse();

    // Apply attack filter
    if (filter === 'attacks') {
      filtered = filtered.filter(packet => packet.attackFlag);
    } else if (filter === 'normal') {
      filtered = filtered.filter(packet => !packet.attackFlag);
    }

    // Apply search
    if (searchTerm) {
      filtered = filtered.filter(packet => 
        JSON.stringify(packet).toLowerCase().includes(searchTerm.toLowerCase())
      );
    }

    return filtered.slice(0, 50); // Show last 50
  };

  const getFunctionCodeName = (code) => {
    const codes = {
      0x03: 'Read Holding',
      0x06: 'Write Single',
      0x10: 'Write Multiple'
    };
    return codes[code] || `FC ${toHex(code, 2)}`;
  };

  const getPacketClass = (packet) => {
    if (packet.attackFlag) return 'packet-attack';
    if (packet.functionCode === 0x06 || packet.functionCode === 0x10) return 'packet-write';
    return 'packet-normal';
  };

  const filteredTraffic = getFilteredTraffic();
  const attackCount = networkTraffic.filter(p => p.attackFlag).length;
  const normalCount = networkTraffic.length - attackCount;

  return (
    <div className="panel network-monitor">
      <div className="panel-header">
        <h2>
          <Network size={20} />
          Network Traffic Monitor
        </h2>
        <div className="traffic-stats">
          <span className="stat-badge normal">{normalCount} Normal</span>
          <span className="stat-badge attack">{attackCount} Attacks</span>
        </div>
      </div>

      <div className="monitor-controls">
        <div className="filter-buttons">
          <button 
            className={`filter-btn ${filter === 'all' ? 'active' : ''}`}
            onClick={() => setFilter('all')}
          >
            All Traffic
          </button>
          <button 
            className={`filter-btn ${filter === 'attacks' ? 'active' : ''}`}
            onClick={() => setFilter('attacks')}
          >
            <Activity size={16} />
            Attacks Only
          </button>
          <button 
            className={`filter-btn ${filter === 'normal' ? 'active' : ''}`}
            onClick={() => setFilter('normal')}
          >
            Normal Only
          </button>
        </div>

        <div className="search-box">
          <Search size={16} />
          <input
            type="text"
            placeholder="Search packets..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
      </div>

      <div className="packet-stream">
        {!isRunning && networkTraffic.length === 0 && (
          <div className="empty-state">
            <Network size={48} />
            <p>No network traffic yet</p>
            <span>Start the simulation to see Modbus packets</span>
          </div>
        )}

        {filteredTraffic.length === 0 && networkTraffic.length > 0 && (
          <div className="empty-state">
            <Filter size={48} />
            <p>No packets match filter</p>
          </div>
        )}

        {filteredTraffic.map(packet => (
          <div 
            key={packet.id || packet.timestamp} 
            className={`packet-card ${getPacketClass(packet)}`}
          >
            <div className="packet-header">
              <span className="packet-time">{formatTimestamp(packet.timestamp)}</span>
              {packet.attackFlag && (
                <span className="attack-badge">{packet.attackType}</span>
              )}
              <span className="packet-function">{getFunctionCodeName(packet.functionCode)}</span>
            </div>

            <div className="packet-details">
              <div className="packet-field">
                <label>Transaction ID:</label>
                <code>{toHex(packet.transactionId, 4)}</code>
              </div>

              <div className="packet-field">
                <label>Protocol ID:</label>
                <code>{toHex(packet.protocolId, 4)}</code>
              </div>

              <div className="packet-field">
                <label>Function Code:</label>
                <code>{toHex(packet.functionCode, 2)}</code>
              </div>

              {packet.startAddress !== undefined && (
                <div className="packet-field">
                  <label>Address:</label>
                  <code>{toHex(packet.startAddress, 4)}</code>
                </div>
              )}

              {packet.value !== undefined && (
                <div className="packet-field">
                  <label>Value:</label>
                  <code>{packet.value}</code>
                </div>
              )}

              {packet.sourceIP && (
                <div className="packet-field">
                  <label>Source IP:</label>
                  <code>{packet.sourceIP}</code>
                </div>
              )}

              {packet.size && (
                <div className="packet-field">
                  <label>Size:</label>
                  <code>{packet.size} bytes</code>
                </div>
              )}
            </div>

            {packet.payload && (
              <div className="packet-payload">
                <label>Payload:</label>
                <pre>{JSON.stringify(packet.payload, null, 2)}</pre>
              </div>
            )}
          </div>
        ))}
      </div>

      <div className="monitor-footer">
        <span>Showing {filteredTraffic.length} of {networkTraffic.length} packets</span>
        {isRunning && (
          <span className="live-indicator">
            <span className="pulse"></span>
            Live
          </span>
        )}
      </div>
    </div>
  );
};

export default NetworkMonitor;
